#!/usr/bin/env node
/**
 * build-areas-seed.mjs - generate supabase/archive/phases/phase78_areas_seed.sql from NYC
 * DCP's 2020 Neighborhood Tabulation Areas.
 *
 * WHY THIS IS A COMMITTED SCRIPT AND NOT A ONE-OFF. DCP republishes the NTA
 * layer; when it does, the seed is regenerated by re-running this file, not by
 * hand-editing 250-odd rows of coordinates. The generator is the source, the
 * .sql is its output.
 *
 * IT NEVER CONTACTS A DATABASE. It reads one local file and writes one .sql
 * file. Applying that .sql is the operator's step, by hand, in the Supabase
 * SQL editor - which is why the output carries a hard size budget.
 *
 * Node standard library only: no dependencies, by policy.
 *
 *   node scripts/build-areas-seed.mjs
 */

import { readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

/**
 * SEED SOURCE. Gitignored scratch, NOT in the repository: .shots/ is the
 * screenshot harness's scratch directory and nothing under it is ever staged.
 * Before re-running this generator, re-download the file:
 *
 *   NYC Open Data -> dataset 4hft-v355
 *   ("2020 Neighborhood Tabulation Areas (NTAs)", Dept. of City Planning)
 *   Export -> GeoJSON  ->  save as .shots/nta2020.geojson
 *
 * The GeoJSON export is roughly 4-5 MB. If the file is missing this script
 * exits non-zero and tells you the same thing.
 */
const SOURCE = join(root, '.shots', 'nta2020.geojson');

/**
 * OPTIONAL ALIAS SOURCE. DCP's colloquial neighbourhood label points. Each
 * point is assigned to the area that contains it, and any label differing
 * from that area's own name becomes an alias. Absent is normal and fine: no
 * aliases are emitted and the summary says so. An alias is NEVER invented.
 */
const ALIAS_SOURCE = join(root, '.shots', 'nhood_names.geojson');

const OUT = join(root, 'supabase', 'archive', 'phases', 'phase78_areas_seed.sql');

/**
 * The operator pastes the output into the Supabase SQL editor by hand, so the
 * emitted file must stay small enough for one paste. Bytes, not MiB.
 */
const BUDGET_BYTES = 1_500_000;

/** Simplification tolerance sweep, in ten-thousandths of a degree. */
const TOL_START = 2; // 0.0002 deg, roughly 22 m
const TOL_MAX = 10; // 0.0010 deg, the continue-path floor for quality

/** Coordinates are rounded to this many decimals: 1e-5 deg is about 1.1 m. */
const COORD_DECIMALS = 5;

/** Metres per degree of latitude. Good to a fraction of a percent over NYC. */
const M_PER_DEG = 111_320;

const BOROUGHS = new Set(['Bronx', 'Brooklyn', 'Manhattan', 'Queens', 'Staten Island']);

const fail = (msg) => {
  console.error(`build-areas-seed: ${msg}`);
  process.exit(1);
};

// ---------------------------------------------------------------------------
// Key discovery. The export's property names are READ OFF THE FILE, never
// assumed: a republished layer that renames a column must be reported, not
// silently mis-parsed.
// ---------------------------------------------------------------------------

function columnStats(featureProps) {
  const keys = new Set();
  for (const p of featureProps) for (const k of Object.keys(p)) keys.add(k);
  const stats = new Map();
  for (const k of keys) {
    const vals = featureProps
      .map((p) => p[k])
      .filter((v) => v !== null && v !== undefined && v !== '')
      .map(String);
    stats.set(k, {
      vals,
      distinct: new Set(vals),
      present: vals.length,
      avgLen: vals.length ? vals.reduce((a, v) => a + v.length, 0) / vals.length : 0,
    });
  }
  return stats;
}

/** Borough: the only key whose entire value set is the five borough names. */
function discoverBoroughKey(stats) {
  for (const [k, s] of stats) {
    if (s.present === 0 || s.distinct.size > 5) continue;
    if ([...s.distinct].every((v) => BOROUGHS.has(v.trim()))) return k;
  }
  return null;
}

/** Code: unique on every feature and shaped like an NTA code (BK0101). */
function discoverCodeKey(stats, total) {
  const hits = [];
  for (const [k, s] of stats) {
    if (s.present !== total || s.distinct.size !== total) continue;
    if (s.vals.every((v) => /^[A-Z]{2}\d{2,4}$/.test(v.trim()))) hits.push(k);
  }
  if (hits.length === 0) return null;
  // Deterministic tie-break: the shortest key name, then alphabetical.
  hits.sort((a, b) => a.length - b.length || a.localeCompare(b));
  return hits[0];
}

/**
 * Name: unique per feature and human-readable. Scored rather than matched, so
 * the abbreviation column ('Grnpt') and the parent-district column - which is
 * NOT unique, and so never reaches the scorer - cannot win.
 */
function discoverNameKey(stats, total, exclude) {
  let best = null;
  for (const [k, s] of stats) {
    // Near-unique rather than strictly unique: if DCP ever ships two areas
    // sharing a label, the name column must still win the scoring instead of
    // silently handing the row to an opaque Socrata id.
    if (exclude.has(k) || s.present !== total || s.distinct.size < total * 0.9) continue;
    const alpha = s.vals.every((v) => /[A-Za-z]/.test(v) && /[a-z]/.test(v));
    if (!alpha || s.avgLen < 4) continue;
    const lk = k.toLowerCase();
    let score = s.avgLen;
    if (lk.includes('name')) score += 100;
    if (lk.includes('abbr')) score -= 100;
    if (best === null || score > best.score) best = { key: k, score };
  }
  return best ? best.key : null;
}

/** Export date: the newest value of any key whose values are all timestamps. */
function discoverExportDate(stats) {
  let newest = null;
  for (const [, s] of stats) {
    if (s.present === 0) continue;
    if (!s.vals.every((v) => /^\d{4}-\d{2}-\d{2}T/.test(v) && !Number.isNaN(Date.parse(v)))) {
      continue;
    }
    for (const v of s.vals) {
      const t = Date.parse(v);
      if (newest === null || t > newest) newest = t;
    }
  }
  return newest === null ? null : new Date(newest).toISOString().slice(0, 10);
}

/**
 * Type: the small-cardinality key naming what kind of area each feature is.
 * DCP marks parks, cemeteries, airports and rail yards here and leaves
 * residential neighbourhoods on one dominant value.
 *
 * The decision fails SAFE. Excluding a park is cosmetic; excluding a real
 * neighbourhood is a hole in the marketplace. So exclusion happens ONLY when
 * one value is unambiguously dominant - it covers at least 70% of features and
 * the minority values together account for no more than 25%. Anything else and
 * every feature is kept, and the summary says the field was inconclusive.
 */
function discoverTypeSplit(stats, total) {
  let cand = null;
  for (const [k, s] of stats) {
    if (s.present !== total) continue;
    if (s.distinct.size < 2 || s.distinct.size > 12) continue;
    if (!s.vals.every((v) => v.length <= 4)) continue;
    const lk = k.toLowerCase();
    const score = (lk.includes('type') ? 100 : 0) - s.distinct.size;
    if (cand === null || score > cand.score) cand = { key: k, score, stats: s };
  }
  if (cand === null) return { key: null, keepValue: null, conclusive: false, counts: new Map() };

  const counts = new Map();
  for (const v of cand.stats.vals) counts.set(v, (counts.get(v) ?? 0) + 1);
  let keepValue = null;
  let keepCount = -1;
  for (const [v, n] of counts) if (n > keepCount) ((keepValue = v), (keepCount = n));

  const dominant = keepCount / total >= 0.7;
  const minorityOk = (total - keepCount) / total <= 0.25;
  return { key: cand.key, keepValue, conclusive: dominant && minorityOk, counts };
}

// ---------------------------------------------------------------------------
// Geometry.
//
// Simplification runs in a locally equal-area-ish space: x = lng * cos(lat0),
// y = lat. One tolerance then means the same distance on both axes, so
// "0.0002 degrees" really is about 22 m east-west as well as north-south.
// Emitted coordinates are always unscaled lng/lat.
// ---------------------------------------------------------------------------

function perpDist(p, a, b) {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  if (dx === 0 && dy === 0) return Math.hypot(p[0] - a[0], p[1] - a[1]);
  let t = ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / (dx * dx + dy * dy);
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  return Math.hypot(p[0] - (a[0] + t * dx), p[1] - (a[1] + t * dy));
}

/**
 * Douglas-Peucker over a list of indices into `pts`, iterative so a ring with
 * thousands of vertices cannot blow the stack. Endpoints are always kept.
 * `stats.maxDrop` collects the largest perpendicular distance actually
 * discarded, which for Douglas-Peucker IS the deviation the simplified line
 * introduces - so the reported metre figure is measured, not assumed.
 */
function dpIndices(list, pts, tol, stats) {
  const n = list.length;
  if (n <= 2) return list.slice();
  const keep = new Uint8Array(n);
  keep[0] = 1;
  keep[n - 1] = 1;
  const stack = [[0, n - 1]];
  while (stack.length > 0) {
    const [i, j] = stack.pop();
    if (j - i < 2) continue;
    const a = pts[list[i]];
    const b = pts[list[j]];
    let dmax = 0;
    let idx = -1;
    for (let k = i + 1; k < j; k++) {
      const d = perpDist(pts[list[k]], a, b);
      if (d > dmax) {
        dmax = d;
        idx = k;
      }
    }
    if (idx === -1) continue;
    if (dmax > tol) {
      keep[idx] = 1;
      stack.push([i, idx], [idx, j]);
    } else if (dmax > stats.maxDrop) {
      stats.maxDrop = dmax;
    }
  }
  const out = [];
  for (let k = 0; k < n; k++) if (keep[k] === 1) out.push(list[k]);
  return out;
}

/**
 * Simplify one closed ring. A ring has no natural endpoints, so it is cut at
 * its first vertex and the vertex farthest from it, each half simplified as an
 * open polyline, and the halves rejoined - the standard way to keep
 * Douglas-Peucker from collapsing a loop onto its own start point.
 */
function simplifyRing(ring, tol, cosLat, stats) {
  const closed =
    ring.length >= 2 &&
    ring[0][0] === ring[ring.length - 1][0] &&
    ring[0][1] === ring[ring.length - 1][1];
  const open = closed ? ring.slice(0, ring.length - 1) : ring.slice();
  const m = open.length;
  if (m < 3) return null;
  if (m <= 4) return open;

  const pts = open.map(([lng, lat]) => [lng * cosLat, lat]);

  let far = 1;
  let fd = -1;
  for (let k = 1; k < m; k++) {
    const d = (pts[k][0] - pts[0][0]) ** 2 + (pts[k][1] - pts[0][1]) ** 2;
    if (d > fd) {
      fd = d;
      far = k;
    }
  }

  const listA = [];
  for (let k = 0; k <= far; k++) listA.push(k);
  const listB = [];
  for (let k = far; k < m; k++) listB.push(k);
  listB.push(0);

  const a = dpIndices(listA, pts, tol, stats);
  const b = dpIndices(listB, pts, tol, stats);
  const merged = a.slice(0, -1).concat(b.slice(0, -1));
  return merged.map((i) => open[i]);
}

const POW = 10 ** COORD_DECIMALS;
const round5 = (v) => Math.round(v * POW) / POW;

/**
 * Round to 5 decimals, drop consecutive duplicates the rounding created, and
 * re-close the ring. Returns null when fewer than 3 distinct vertices survive:
 * such a ring has no area and contributes nothing to an even-odd test.
 */
function roundAndClose(open) {
  const out = [];
  for (const [lng, lat] of open) {
    const p = [round5(lng), round5(lat)];
    const last = out[out.length - 1];
    if (last && last[0] === p[0] && last[1] === p[1]) continue;
    out.push(p);
  }
  while (
    out.length > 1 &&
    out[0][0] === out[out.length - 1][0] &&
    out[0][1] === out[out.length - 1][1]
  ) {
    out.pop();
  }
  if (out.length < 3) return null;
  out.push([out[0][0], out[0][1]]);
  return out;
}

/** Every ring of a Polygon or MultiPolygon, flattened. Holes are just rings. */
function ringsOf(geometry) {
  if (!geometry) return [];
  if (geometry.type === 'Polygon') return geometry.coordinates;
  if (geometry.type === 'MultiPolygon') return geometry.coordinates.flat();
  return [];
}

/**
 * Even-odd point-in-polygon, deliberately a line-for-line mirror of
 * area_for_point() in phase78_properties_and_areas.sql - including toggling
 * across ALL of an area's rings rather than per ring, and treating a
 * horizontal edge as no crossing (SQL's nullif(y2-y1,0) yields null, which is
 * not true). If this and the SQL ever disagree, a seeded centroid could sit
 * outside the area the database thinks it is in.
 */
function insideRings(rings, lat, lng) {
  let inside = false;
  for (const ring of rings) {
    const n = ring.length;
    if (n < 3) continue;
    for (let i = 0; i < n; i++) {
      const [x1, y1] = ring[i];
      const [x2, y2] = ring[(i + 1) % n];
      if (y1 > lat !== y2 > lat) {
        const denom = y2 - y1;
        if (denom !== 0 && lng < ((x2 - x1) * (lat - y1)) / denom + x1) inside = !inside;
      }
    }
  }
  return inside;
}

/**
 * The midpoint of the longest horizontal chord that lies inside the area.
 * Scanlines are taken BETWEEN consecutive distinct vertex latitudes so no
 * scanline ever passes exactly through a vertex, which is where an even-odd
 * crossing count goes ambiguous.
 */
function longestScanlineMidpoint(rings) {
  const lats = [...new Set(rings.flat().map((p) => p[1]))].sort((a, b) => a - b);
  let cands = [];
  for (let i = 0; i + 1 < lats.length; i++) {
    const mid = (lats[i] + lats[i + 1]) / 2;
    if (mid > lats[i] && mid < lats[i + 1]) cands.push(mid);
  }
  if (cands.length === 0) return null;
  const MAX = 512;
  if (cands.length > MAX) {
    const step = cands.length / MAX;
    const thinned = [];
    for (let i = 0; i < MAX; i++) thinned.push(cands[Math.floor(i * step)]);
    cands = thinned;
  }

  let best = null;
  for (const lat of cands) {
    const xs = [];
    for (const ring of rings) {
      const n = ring.length;
      if (n < 3) continue;
      for (let i = 0; i < n; i++) {
        const [x1, y1] = ring[i];
        const [x2, y2] = ring[(i + 1) % n];
        if (y1 > lat !== y2 > lat) xs.push(x1 + ((lat - y1) / (y2 - y1)) * (x2 - x1));
      }
    }
    xs.sort((a, b) => a - b);
    for (let i = 0; i + 1 < xs.length; i += 2) {
      const w = xs[i + 1] - xs[i];
      if (best === null || w > best.w) best = { w, lat, lng: (xs[i] + xs[i + 1]) / 2 };
    }
  }
  return best;
}

/**
 * A centroid that is genuinely INSIDE the area. The average of the vertices is
 * tried first; for a crescent, a horseshoe or a two-part area that point falls
 * outside, and the longest-scanline midpoint is used instead. Whichever is
 * chosen is re-tested AFTER rounding, because rounding can push a point across
 * a nearby edge.
 */
function pickCentroid(rings) {
  let sx = 0;
  let sy = 0;
  let n = 0;
  for (const ring of rings) {
    for (let i = 0; i + 1 < ring.length; i++) {
      sx += ring[i][0];
      sy += ring[i][1];
      n++;
    }
  }
  if (n === 0) return null;

  const tryPoint = (lat, lng, fallback) => {
    for (const dec of [6, 8, 12]) {
      const p = 10 ** dec;
      const rl = Math.round(lat * p) / p;
      const rg = Math.round(lng * p) / p;
      if (insideRings(rings, rl, rg)) return { lat: rl, lng: rg, fallback };
    }
    return null;
  };

  const avg = tryPoint(sy / n, sx / n, false);
  if (avg) return avg;

  const sl = longestScanlineMidpoint(rings);
  if (!sl) return null;
  return tryPoint(sl.lat, sl.lng, true);
}

// ---------------------------------------------------------------------------
// SQL emission.
// ---------------------------------------------------------------------------

/** Single quotes are doubled. Names go in VERBATIM otherwise. */
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;

/** Shortest exact decimal form, so the paste budget is not spent on zeros. */
function num(v, decimals) {
  const s = v.toFixed(decimals).replace(/0+$/, '').replace(/\.$/, '');
  return s === '-0' ? '0' : s;
}

const ringsLiteral = (rings) =>
  `[${rings
    .map((r) => `[${r.map((p) => `[${num(p[0], COORD_DECIMALS)},${num(p[1], COORD_DECIMALS)}]`).join(',')}]`)
    .join(',')}]`;

const COLS =
  'code, name, display_name, borough, centroid_lat, centroid_lng, ' +
  'min_lat, max_lat, min_lng, max_lng, rings';

/**
 * The conflict branch refreshes what DCP owns and NOTHING the operator owns.
 * display_name and aliases are deliberately absent: they are the editable copy
 * and the editable synonym list, and a re-seed must never overwrite either.
 */
const CONFLICT =
  'on conflict (code) do update set name = excluded.name, borough = excluded.borough, ' +
  'centroid_lat = excluded.centroid_lat, centroid_lng = excluded.centroid_lng, ' +
  'min_lat = excluded.min_lat, max_lat = excluded.max_lat, ' +
  'min_lng = excluded.min_lng, max_lng = excluded.max_lng, rings = excluded.rings;';

function emitSql(areas, meta) {
  const L = [];
  L.push('-- ' + '='.repeat(74));
  L.push('-- phase78_areas_seed.sql');
  L.push('--');
  L.push('-- GENERATED FILE - DO NOT HAND-EDIT. Regenerate with:');
  L.push('--');
  L.push('--     node scripts/build-areas-seed.mjs');
  L.push('--');
  L.push('-- Source dataset : NYC Open Data 4hft-v355 - "2020 Neighborhood Tabulation');
  L.push('--                  Areas (NTAs)", NYC Department of City Planning.');
  L.push('--                  Export -> GeoJSON -> .shots/nta2020.geojson (gitignored).');
  L.push(`-- Export date    : ${meta.exportDate ?? 'not carried by the export'}`);
  L.push(`-- Rows           : ${areas.length}`);
  L.push(`-- Simplification : Douglas-Peucker at ${meta.tolerance} degrees`);
  L.push(`--                  (about ${Math.round(meta.tolerance * M_PER_DEG)} m), coordinates`);
  L.push(`--                  rounded to ${COORD_DECIMALS} decimals. Largest deviation`);
  L.push(`--                  introduced: ${meta.maxDeviationM.toFixed(1)} m.`);
  L.push('--');
  L.push('-- SEEDS public.areas, created empty by phase78_properties_and_areas.sql.');
  L.push('-- Until this file is applied, area_for_point() returns null for every point.');
  L.push('--');
  L.push('-- THIS FILE NEVER DELETES A ROW. Areas are referenced by jobs and by');
  L.push('-- properties; retiring one is an operator decision, never a generator run.');
  L.push('-- A row that DCP has dropped simply stops being refreshed.');
  L.push('--');
  L.push('-- display_name is seeded equal to name and, like aliases, is NEVER touched by');
  L.push('-- the conflict branch: both are the operator-editable copy. Re-run this file');
  L.push('-- as often as you like; hand edits to those two columns survive.');
  L.push('--');
  L.push('-- rings is an array of rings, each an array of [lng, lat] pairs - LONGITUDE');
  L.push('-- FIRST, matching GeoJSON and matching what area_for_point() reads. Holes and');
  L.push('-- detached parts are just more rings under the even-odd rule.');
  L.push('--');
  L.push('-- Area names are VERBATIM from the source, apostrophes and dashes included');
  L.push('-- (single quotes are doubled for SQL). This header and its comments are ASCII');
  L.push('-- only; the data is whatever DCP published.');
  if (meta.nonAsciiNames.length > 0) {
    L.push('--');
    L.push('-- Names carrying a non-ASCII character, listed so their presence is');
    L.push('-- deliberate rather than a surprise:');
    for (const n of meta.nonAsciiNames) L.push(`--   ${n.code} ${JSON.stringify(n.name)}`);
  }
  L.push('--');
  L.push(`-- Aliases: ${meta.aliasNote}`);
  L.push('--');
  L.push('-- ASCII only. One transaction. Safe to run more than once.');
  L.push('-- ' + '='.repeat(74));
  L.push('');
  L.push('begin;');
  L.push('');
  L.push('set local search_path = public, pg_temp;');
  L.push('');

  for (const a of areas) {
    L.push(`insert into public.areas (${COLS}) values`);
    L.push(
      `  (${q(a.code)}, ${q(a.name)}, ${q(a.name)}, ${q(a.borough)}, ` +
        `${num(a.centroidLat, 12)}, ${num(a.centroidLng, 12)}, ` +
        `${num(a.minLat, COORD_DECIMALS)}, ${num(a.maxLat, COORD_DECIMALS)}, ` +
        `${num(a.minLng, COORD_DECIMALS)}, ${num(a.maxLng, COORD_DECIMALS)}, ` +
        `${q(ringsLiteral(a.rings))}::jsonb)`
    );
    L.push(`  ${CONFLICT}`);
  }

  L.push('');
  L.push('-- ' + '-'.repeat(73));
  L.push('-- Self-check. Any failure raises and rolls the whole file back.');
  L.push('-- ' + '-'.repeat(73));
  L.push('do $$');
  L.push('declare');
  L.push(`  v_expected constant integer := ${areas.length};`);
  L.push('  v_actual   integer;');
  L.push('  v_bad      integer;');
  L.push('begin');
  L.push('  select count(*) into v_actual from public.areas;');
  L.push('  if v_actual < floor(v_expected * 0.9) or v_actual > ceil(v_expected * 1.1) then');
  L.push(
    "    raise exception 'PHASE78 SEED SELF-CHECK FAIL (a): public.areas holds % row(s), " +
      "expected % within 10%%', v_actual, v_expected;"
  );
  L.push('  end if;');
  L.push('');
  L.push('  select count(*) into v_bad from public.areas');
  L.push('   where min_lat >= max_lat or min_lng >= max_lng;');
  L.push('  if v_bad > 0 then');
  L.push(
    "    raise exception 'PHASE78 SEED SELF-CHECK FAIL (b): % row(s) carry an " +
      "inconsistent bounding box', v_bad;"
  );
  L.push('  end if;');
  L.push('');
  L.push("  raise notice 'PHASE78 SEED SELF-CHECK PASS: % row(s), every bounding box self-consistent', v_actual;");
  L.push('end $$;');
  L.push('');
  L.push('commit;');
  L.push('');
  return L.join('\n');
}

// ---------------------------------------------------------------------------
// Build.
// ---------------------------------------------------------------------------

function buildAreas(features, keys, split, tolerance, cosLat) {
  const stats = { maxDrop: 0 };
  const areas = [];
  const excluded = [];
  let unsimplifiedRings = 0;
  let droppedRings = 0;
  let fallbacks = 0;
  const problems = [];

  for (const f of features) {
    const p = f.properties ?? {};
    const code = String(p[keys.code] ?? '').trim();
    const name = String(p[keys.name] ?? '').trim();
    const borough = String(p[keys.borough] ?? '').trim();

    if (split.conclusive && String(p[split.key]) !== split.keepValue) {
      excluded.push({ code, name, type: String(p[split.key]) });
      continue;
    }
    if (!code || !name || !borough) {
      problems.push(`feature ${code || '(no code)'} is missing a code, name or borough`);
      continue;
    }
    if (!BOROUGHS.has(borough)) {
      problems.push(`${code}: borough ${JSON.stringify(borough)} is not one of the five`);
      continue;
    }

    const rings = [];
    for (const raw of ringsOf(f.geometry)) {
      let ring = null;
      const simplified = simplifyRing(raw, tolerance, cosLat, stats);
      if (simplified) ring = roundAndClose(simplified);
      if (!ring) {
        // Below three vertices after simplification: keep the ring as DCP drew
        // it rather than lose a boundary. Cosmetically larger, never wrong.
        const open =
          raw.length >= 2 &&
          raw[0][0] === raw[raw.length - 1][0] &&
          raw[0][1] === raw[raw.length - 1][1]
            ? raw.slice(0, raw.length - 1)
            : raw;
        ring = roundAndClose(open);
        if (ring) unsimplifiedRings++;
        else droppedRings++;
      }
      if (ring) rings.push(ring);
    }

    if (rings.length === 0) {
      problems.push(`${code}: every ring collapsed - no geometry left to store`);
      continue;
    }

    let minLat = Infinity;
    let maxLat = -Infinity;
    let minLng = Infinity;
    let maxLng = -Infinity;
    for (const ring of rings) {
      for (const [lng, lat] of ring) {
        if (lat < minLat) minLat = lat;
        if (lat > maxLat) maxLat = lat;
        if (lng < minLng) minLng = lng;
        if (lng > maxLng) maxLng = lng;
      }
    }
    if (!(minLat < maxLat) || !(minLng < maxLng)) {
      problems.push(`${code}: bounding box is not self-consistent`);
      continue;
    }

    const c = pickCentroid(rings);
    if (!c) {
      problems.push(`${code}: could not place a centroid inside the area`);
      continue;
    }
    if (c.fallback) fallbacks++;
    if (c.lat < minLat || c.lat > maxLat || c.lng < minLng || c.lng > maxLng) {
      problems.push(`${code}: centroid falls outside its own bounding box`);
      continue;
    }

    areas.push({
      code,
      name,
      borough,
      centroidLat: c.lat,
      centroidLng: c.lng,
      minLat,
      maxLat,
      minLng,
      maxLng,
      rings,
    });
  }

  const seen = new Set();
  for (const a of areas) {
    if (seen.has(a.code)) problems.push(`duplicate code ${a.code} - it is the primary key`);
    seen.add(a.code);
  }

  return {
    areas,
    excluded,
    problems,
    fallbacks,
    unsimplifiedRings,
    droppedRings,
    maxDropDeg: stats.maxDrop,
  };
}

// ---------------------------------------------------------------------------
// Main.
// ---------------------------------------------------------------------------

if (!existsSync(SOURCE)) {
  fail(
    `seed source absent: ${SOURCE}\n` +
      '  Download NYC Open Data dataset 4hft-v355 ("2020 Neighborhood Tabulation\n' +
      '  Areas"), Export -> GeoJSON, and save it at that path. It is gitignored\n' +
      '  scratch and is deliberately not in the repository.'
  );
}

const sourceBytes = statSync(SOURCE).size;
let doc;
try {
  doc = JSON.parse(readFileSync(SOURCE, 'utf8'));
} catch (err) {
  fail(`${SOURCE} is not parseable JSON: ${err.message}`);
}

const features = (doc.features ?? []).filter((f) => f && f.geometry);
if (features.length === 0) fail('the export carries no features with geometry');

const props = features.map((f) => f.properties ?? {});
const stats = columnStats(props);

const boroughKey = discoverBoroughKey(stats);
const codeKey = discoverCodeKey(stats, features.length);
const nameKey = discoverNameKey(stats, features.length, new Set([codeKey, boroughKey]));
if (!boroughKey || !codeKey || !nameKey) {
  fail(
    'could not discover the code/name/borough keys from the export. Keys present: ' +
      [...stats.keys()].join(', ') +
      `\n  code=${codeKey ?? 'NOT FOUND'} name=${nameKey ?? 'NOT FOUND'} ` +
      `borough=${boroughKey ?? 'NOT FOUND'}`
  );
}
const keys = { code: codeKey, name: nameKey, borough: boroughKey };

const split = discoverTypeSplit(stats, features.length);
const exportDate = discoverExportDate(stats);

let sumLat = 0;
let latN = 0;
for (const f of features) {
  for (const ring of ringsOf(f.geometry)) {
    for (const p of ring) {
      sumLat += p[1];
      latN++;
    }
  }
}
if (latN === 0) fail('the export carries no coordinates');
const cosLat = Math.cos(((sumLat / latN) * Math.PI) / 180);

let built = null;
let sql = '';
let tolerance = 0;
let overBudget = false;
for (let step = TOL_START; step <= TOL_MAX; step++) {
  tolerance = step / 10_000;
  built = buildAreas(features, keys, split, tolerance, cosLat);
  if (built.problems.length > 0) break;

  const roundingM = Math.hypot(0.5 / POW, (0.5 / POW) * cosLat) * M_PER_DEG;
  sql = emitSql(built.areas, {
    tolerance,
    exportDate,
    maxDeviationM: built.maxDropDeg * M_PER_DEG + roundingM,
    nonAsciiNames: built.areas
      .filter((a) => /[^\x20-\x7e]/.test(a.name))
      .map((a) => ({ code: a.code, name: a.name })),
    aliasNote: existsSync(ALIAS_SOURCE)
      ? 'seeded from .shots/nhood_names.geojson'
      : 'none. The optional label-point source .shots/nhood_names.geojson was ' +
        'not present, so no alias is emitted. Aliases are never invented.',
  });
  if (Buffer.byteLength(sql, 'utf8') <= BUDGET_BYTES) break;
  overBudget = true;
}

if (built.problems.length > 0) {
  console.error('build-areas-seed: INCONSISTENT INPUT, nothing written:');
  for (const p of built.problems.slice(0, 20)) console.error(`  - ${p}`);
  if (built.problems.length > 20) {
    console.error(`  ... and ${built.problems.length - 20} more`);
  }
  process.exit(1);
}

const bytes = Buffer.byteLength(sql, 'utf8');
const fits = bytes <= BUDGET_BYTES;
writeFileSync(OUT, sql, 'utf8');

// ---------------------------------------------------------------------------
// Summary.
// ---------------------------------------------------------------------------

const roundingM = Math.hypot(0.5 / POW, (0.5 / POW) * cosLat) * M_PER_DEG;
const deviationM = built.maxDropDeg * M_PER_DEG + roundingM;
const points = built.areas.reduce((n, a) => n + a.rings.reduce((m, r) => m + r.length, 0), 0);
const nonAscii = built.areas.filter((a) => /[^\x20-\x7e]/.test(a.name));
const byBorough = new Map();
for (const a of built.areas) byBorough.set(a.borough, (byBorough.get(a.borough) ?? 0) + 1);

console.log('build-areas-seed');
console.log(`  source            : ${SOURCE} (${sourceBytes.toLocaleString()} bytes)`);
console.log(`  export date       : ${exportDate ?? 'not carried by the export'}`);
console.log(`  features read     : ${features.length}`);
console.log(
  `  property keys     : code=${keys.code}  name=${keys.name}  borough=${keys.borough}` +
    `  type=${split.key ?? 'NOT FOUND'}`
);
if (split.key) {
  const counts = [...split.counts].sort((a, b) => b[1] - a[1]);
  console.log(
    `  ${split.key} values : ` + counts.map(([v, n]) => `${JSON.stringify(v)}=${n}`).join('  ')
  );
}
if (split.conclusive) {
  console.log(
    `  excluded          : ${built.excluded.length} non-residential ` +
      `(${split.key} <> ${JSON.stringify(split.keepValue)})`
  );
  for (const e of built.excluded) console.log(`      ${e.code}  ${split.key}=${e.type}  ${e.name}`);
} else {
  console.log(
    '  excluded          : 0 - the type field was INCONCLUSIVE, so every feature was'
  );
  console.log(
    '                      kept. A park in the list is cosmetic; a missing'
  );
  console.log('                      neighbourhood is real.');
}
console.log(`  rows emitted      : ${built.areas.length}`);
console.log(
  `  by borough        : ` +
    [...byBorough].sort((a, b) => a[0].localeCompare(b[0])).map(([b, n]) => `${b}=${n}`).join('  ')
);
console.log(`  tolerance         : ${tolerance} deg (about ${Math.round(tolerance * M_PER_DEG)} m)`);
console.log(
  `  max deviation     : ${deviationM.toFixed(1)} m ` +
    `(${(built.maxDropDeg * M_PER_DEG).toFixed(1)} m simplification + ` +
    `${roundingM.toFixed(2)} m rounding)`
);
console.log(`  rings kept whole  : ${built.unsimplifiedRings} (would have fallen below 3 points)`);
console.log(`  rings dropped     : ${built.droppedRings} (degenerate, zero area)`);
console.log(`  coordinate pairs  : ${points.toLocaleString()}`);
console.log(`  centroid fallback : ${built.fallbacks} area(s) needed the longest-scanline midpoint`);
console.log(
  `  non-ASCII names   : ` +
    (nonAscii.length === 0
      ? 'none'
      : nonAscii.map((a) => `${a.code} ${JSON.stringify(a.name)}`).join('  '))
);
console.log(
  `  aliases           : ` +
    (existsSync(ALIAS_SOURCE)
      ? 'seeded from .shots/nhood_names.geojson'
      : 'none - .shots/nhood_names.geojson is absent, so none were emitted')
);
console.log(`  output            : ${OUT}`);
console.log(
  `  output bytes      : ${bytes.toLocaleString()} / ${BUDGET_BYTES.toLocaleString()} budget` +
    (fits ? ' - fits one paste' : ' - OVER BUDGET')
);
if (!fits) {
  console.log(
    `  NOTE: the budget is unreachable even at ${TOL_MAX / 10_000} deg. The file is`
  );
  console.log('        emitted anyway; the operator must paste it in two halves.');
} else if (overBudget) {
  console.log(`  NOTE: tolerance was raised from ${TOL_START / 10_000} deg to fit the budget.`);
}

if (built.areas.length === 0) fail('no rows emitted');
